ALTER TABLE ISTANZE ADD (CODICEPRATICATEL varchar(40) NULL);
ALTER TABLE CONFIGURAZIONE ADD (CODICE_ACCREDITAMENTO varchar(30));
CREATE OR REPLACE ALGORITHM=TEMPTABLE VIEW VW_LISTAPRATICHE AS select istanze.CODICECOMUNE AS codicecomune,istanze.IDCOMUNE AS idcomune,istanze.SOFTWARE AS software,software.DESCRIZIONELUNGA AS descsoftware,istanze.CODICEISTANZA AS idpratica,istanze.NUMEROISTANZA AS numeropratica,date_format(istanze.DATA,_utf8'%d/%m/%Y') AS datapresentazione,date_format(istanze.DATA,_utf8'%Y') AS annopresentazione,date_format(istanze.DATA,_utf8'%m') AS mesepresentazione,istanze.NUMEROPROTOCOLLO AS numeroprotocollo,date_format(istanze.DATAPROTOCOLLO,_utf8'%d/%m/%Y') AS dataprotocollo,istanze.CODICEINTERVENTOPROC AS codiceintervento,vw_alberoproc.SC_DESCRIZIONE AS descrizioneintervento,tipiprocedure.CODICEPROCEDURA AS codiceprocedura,tipiprocedure.PROCEDURA AS procedura,istanze.LAVORI AS oggetto,ucase(istanze.LAVORI) AS oggettou,istanze.CHIUSURA AS codstatopratica,statiistanza.STATO AS statopratica,responsabili.RESPONSABILE AS responsabile,responsabili.TELEFONOLAVORO AS responsabile_telefono,ifnull(stradario.CODVIARIO,stradario.CODICESTRADARIO) AS pr_codviario,concat_ws(_utf8'',stradario.PREFISSO,_utf8' ',stradario.DESCRIZIONE) AS pr_indirizzo,istanzestradario.CODICECIVICO AS pr_codcivico,istanze.CIVICO AS pr_civico,istanze.CODICEAREA AS codicezonizzazione,aree.DENOMINAZIONE AS zonizzazione,anagrafe.CODICEANAGRAFE AS CodiceRichiedente,ifnull(anagrafe.CODICEFISCALE,_utf8'') AS codicefiscale,ifnull(anagrafe.PARTITAIVA,_utf8'') AS partitaiva,concat_ws(_utf8'',anagrafe.NOMINATIVO,_utf8' ',anagrafe.NOME) AS nominativo,anagrafe.INDIRIZZO AS indirizzo,anagrafe.CAP AS cap,anagrafe.CITTA AS localita,comuneresidenza.COMUNE AS citta,comuneresidenza.PROVINCIA AS provincia,tipisoggetto.TIPOSOGGETTO AS tiporapporto,catasto.DESCRIZIONE AS tipocatasto,istanzemappali.FOGLIO AS foglio,istanzemappali.PARTICELLA AS particella,istanzemappali.SUB AS sub,tecnico.CODICEANAGRAFE AS tec_codice,concat_ws(_utf8'',tecnico.NOMINATIVO,_utf8' ',tecnico.NOME) AS tec_nominativo,ifnull(tecnico.CODICEFISCALE,_utf8'') AS tec_codicefiscale,ifnull(tecnico.PARTITAIVA,_utf8'') AS tec_partitaiva,azienda.CODICEANAGRAFE AS az_codice,concat_ws(_utf8'',azienda.NOMINATIVO,_utf8' ',azienda.NOME) AS az_nominativo,ifnull(azienda.CODICEFISCALE,_utf8'') AS az_codicefiscale,ifnull(azienda.PARTITAIVA,_utf8'') AS az_partitaiva,istruttori.RESPONSABILE AS istruttore,istruttori.TELEFONOLAVORO AS istruttore_telefono,operatori.RESPONSABILE AS operatore,operatori.TELEFONOLAVORO AS operatore_telefono from 
(((((((((((((((istanze left join anagrafe tecnico on(((istanze.IDCOMUNE = tecnico.IDCOMUNE) and (istanze.CODICEPROFESSIONISTA = tecnico.CODICEANAGRAFE)))) left join anagrafe azienda on(((istanze.IDCOMUNE = azienda.IDCOMUNE) and (istanze.CODICETITOLARELEGALE = azienda.CODICEANAGRAFE)))) left join (istanzemappali left join catasto on((istanzemappali.CODICECATASTO = catasto.CODICE))) on(((istanze.IDCOMUNE = istanzemappali.IDCOMUNE) and (istanze.CODICEISTANZA = istanzemappali.FKCODICEISTANZA)))) left join responsabili on(((istanze.IDCOMUNE = responsabili.IDCOMUNE) and (istanze.CODICERESPONSABILEPROC = responsabili.CODICERESPONSABILE)))) left join tipisoggetto on(((istanze.IDCOMUNE = tipisoggetto.IDCOMUNE) and (istanze.FKCODICESOGGETTO = tipisoggetto.CODICETIPOSOGGETTO)))) left join aree on(((istanze.IDCOMUNE = aree.IDCOMUNE) and (istanze.CODICEAREA = aree.CODICEAREA)))) left join tipiprocedure on(((istanze.IDCOMUNE = tipiprocedure.IDCOMUNE) and (istanze.CODICEPROCEDURA = tipiprocedure.CODICEPROCEDURA)))) left join responsabili istruttori on(((istanze.IDCOMUNE = istruttori.IDCOMUNE) and (istanze.CODICEISTRUTTORE = istruttori.CODICERESPONSABILE)))) left join responsabili operatori on(((istanze.IDCOMUNE = operatori.IDCOMUNE) and (istanze.CODICERESPONSABILE = operatori.CODICERESPONSABILE)))) join (anagrafe left join comuni comuneresidenza on((anagrafe.COMUNERESIDENZA = comuneresidenza.CODICECOMUNE)))) join software) join istanzestradario) join stradario) join vw_alberoproc) join statiistanza) WHERE 
((software.CODICE = istanze.SOFTWARE) and (anagrafe.IDCOMUNE = istanze.IDCOMUNE) and (anagrafe.CODICEANAGRAFE = istanze.CODICERICHIEDENTE) and (statiistanza.IDCOMUNE = istanze.IDCOMUNE) and (statiistanza.SOFTWARE = istanze.SOFTWARE) and (statiistanza.CODICESTATO = istanze.CHIUSURA) and (istanzestradario.IDCOMUNE = istanze.IDCOMUNE) and (istanzestradario.CODICEISTANZA = istanze.CODICEISTANZA) and (istanzestradario.PRIMARIO = 1) and (stradario.IDCOMUNE = istanzestradario.IDCOMUNE) and (stradario.CODICESTRADARIO = istanzestradario.CODICESTRADARIO) and (istanzemappali.PRIMARIO = 1) and (vw_alberoproc.IDCOMUNE = istanze.IDCOMUNE) and (vw_alberoproc.SC_ID = istanze.CODICEINTERVENTOPROC));